<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { useI18n } from "vue-i18n";
import { Plus, Refresh, View } from "@element-plus/icons-vue";
import { systemAPI, type PlatformDashboard } from "@/api/adminSystem";
import { operationsAPI, type OpsRecord } from "@/api/adminStability";
import { formatBackendTime } from "@/utils/timezone";
const {t}=useI18n(),router=useRouter();
const loading=ref(false),data=ref<PlatformDashboard>();
const operations=ref<Record<string, unknown>>({});
function rows(value:unknown){return Array.isArray(value)?value as OpsRecord[]:[]}
function healthStatus(value:unknown){const list=rows(value);if(list.some(row=>['UNAVAILABLE','UNHEALTHY'].includes(String(row.operationalStatus||row.healthStatus))))return 'UNHEALTHY';if(list.some(row=>['DEGRADED','MAINTENANCE'].includes(String(row.operationalStatus||row.healthStatus))))return 'DEGRADED';return list.length?'HEALTHY':'UNKNOWN'}
const opsCards=computed(()=>[
  {key:'tenantsInMaintenance',value:Number((operations.value.maintenance as Record<string,unknown>|undefined)?.total||0)},
  {key:'paymentHealth',value:healthStatus((operations.value.payment as Record<string,unknown>|undefined)?.health)},
  {key:'providerHealth',value:healthStatus((operations.value.provider as Record<string,unknown>|undefined)?.list)},
  {key:'criticalAlerts',value:Number((operations.value.alerts as Record<string,unknown>|undefined)?.total||0)},
  {key:'failedJobs',value:rows((operations.value.jobs as Record<string,unknown>|undefined)?.failedExecutions).filter(row=>row.status==='FAILED').length},
  {key:'queueBacklog',value:Number((rows((operations.value.health as Record<string,unknown>|undefined)?.components).find(row=>row.componentCode==='message-queue')?.details as Record<string,unknown>|undefined)?.count||0)},
  {key:'latestBackup',value:String(rows((operations.value.backups as Record<string,unknown>|undefined)?.list)[0]?.status||'UNKNOWN')},
  {key:'releaseFailures',value:Number((operations.value.releases as Record<string,unknown>|undefined)?.total||0)},
]);
async function load(){loading.value=true;try{const results=await Promise.allSettled([systemAPI.platformDashboard(),operationsAPI.maintenance.tenants({enabled:true,page:1,pageSize:1}),operationsAPI.monitor.payments({}),operationsAPI.monitor.providers({}),operationsAPI.alerts.list({status:'OPEN',severity:'CRITICAL',page:1,pageSize:1}),operationsAPI.jobs.overview({}),operationsAPI.health(),operationsAPI.backups.list({page:1,pageSize:1}),operationsAPI.releases.list({status:'FAILED',page:1,pageSize:1})]);if(results[0].status==='fulfilled')data.value=results[0].value;const keys=['maintenance','payment','provider','alerts','jobs','health','backups','releases'];keys.forEach((key,index)=>{const result=results[index+1];if(result.status==='fulfilled')operations.value[key]=result.value})}finally{loading.value=false}}
const money=(value:string)=>new Intl.NumberFormat(undefined,{maximumFractionDigits:2,minimumFractionDigits:2}).format(Number(value||0));
onMounted(load);
</script>
<template><main class="platform-dashboard" v-loading="loading"><header class="page-heading"><div><p>{{t('portal.platform.badge')}}</p><h1>{{t('platformDashboard.title')}}</h1><span>{{t('platformDashboard.description')}}</span></div><div class="heading-actions"><el-tooltip :content="t('common.refresh')"><el-button circle :icon="Refresh" @click="load"/></el-tooltip><el-button type="primary" size="large" :icon="Plus" @click="router.push('/platform/tenants/create')">{{t('portal.createBrand')}}</el-button></div></header><section class="metric-grid"><article v-for="key in ['totalTenants','activeTenants','totalSites','totalPlayers','pendingDomains','runningJobs']" :key="key"><span>{{t(`platformDashboard.metrics.${key}`)}}</span><strong>{{Number(data?.overview?.[key as keyof PlatformDashboard['overview']]||0).toLocaleString()}}</strong></article></section><section class="ops-grid"><article v-for="item in opsCards" :key="item.key"><span>{{t(`opsV1.dashboard.${item.key}`)}}</span><el-tag v-if="typeof item.value==='string'" :type="item.value==='HEALTHY'||item.value==='SUCCESS'?'success':item.value==='UNKNOWN'?'info':'warning'">{{item.value}}</el-tag><strong v-else>{{item.value}}</strong></article></section><section class="content-grid"><div class="table-band finance"><div class="section-heading"><h2>{{t('platformDashboard.financeTitle')}}</h2><span>{{t('platformDashboard.today')}}</span></div><el-table :data="data?.financeByCurrency||[]"><el-table-column prop="currency" :label="t('tenantCenter.fields.currency')" width="70"><template #default="{row}"><el-tag effect="plain">{{row.currency}}</el-tag></template></el-table-column><el-table-column :label="t('platformDashboard.metrics.totalBet')" min-width="100" align="right"><template #default="{row}">{{money(row.totalBet)}}</template></el-table-column><el-table-column label="GGR" min-width="95" align="right"><template #default="{row}"><strong :class="Number(row.ggr)<0?'loss':'profit'">{{money(row.ggr)}}</strong></template></el-table-column><el-table-column label="NGR" min-width="95" align="right"><template #default="{row}"><strong :class="Number(row.ngr)<0?'loss':'profit'">{{money(row.ngr)}}</strong></template></el-table-column><el-table-column :label="t('platformDashboard.metrics.deposit')" min-width="95" align="right"><template #default="{row}">{{money(row.deposit)}}</template></el-table-column><el-table-column :label="t('platformDashboard.metrics.withdrawal')" min-width="95" align="right"><template #default="{row}">{{money(row.withdrawal)}}</template></el-table-column></el-table></div><div class="table-band providers"><div class="section-heading"><h2>{{t('platformDashboard.providerTitle')}}</h2></div><el-table :data="data?.providers||[]"><el-table-column prop="name" label="Provider" min-width="130"><template #default="{row}"><el-tag>{{row.providerCode}}</el-tag><span class="provider-name">{{row.name}}</span></template></el-table-column><el-table-column prop="apiStatus" :label="t('common.status')" width="100"><template #default="{row}"><el-tag :type="['UP','HEALTHY','ACTIVE'].includes(String(row.apiStatus))?'success':'danger'">{{row.apiStatus||'UNKNOWN'}}</el-tag></template></el-table-column><el-table-column prop="lastSyncAt" :label="t('platformDashboard.lastSync')" width="110"><template #default="{row}">{{row.lastSyncAt?formatBackendTime(String(row.lastSyncAt)).slice(0,10):'-'}}</template></el-table-column></el-table></div></section><section class="table-band"><div class="section-heading"><h2>{{t('platformDashboard.recentTenants')}}</h2><el-button link type="primary" @click="router.push('/system/tenants')">{{t('platformDashboard.viewAll')}}</el-button></div><el-table :data="data?.recentTenants||[]"><el-table-column prop="tenantName" :label="t('tenantCenter.fields.tenantName')" min-width="170"><template #default="{row}"><strong>{{row.tenantName}}</strong><small>{{row.tenantCode}}</small></template></el-table-column><el-table-column prop="countryCode" :label="t('tenantCenter.fields.country')" width="100"/><el-table-column :label="t('common.status')" width="100"><template #default="{row}"><el-switch :model-value="row.enabled" disabled/></template></el-table-column><el-table-column prop="primaryDomain" :label="t('tenantCenter.fields.domain')" min-width="190"/><el-table-column prop="playerCount" :label="t('tenantCenter.fields.players')" width="110" align="right"/><el-table-column prop="createdAt" :label="t('common.createdAt')" width="175"><template #default="{row}">{{formatBackendTime(row.createdAt)}}</template></el-table-column><el-table-column width="70"><template #default="{row}"><el-button circle :icon="View" @click="router.push(`/system/tenants/${row.id}`)"/></template></el-table-column></el-table></section></main></template>
<style scoped>.platform-dashboard{display:flex;flex-direction:column;gap:16px;min-height:360px}.page-heading,.section-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.page-heading p{margin:0 0 4px;color:#337ecc;font-size:12px;font-weight:700;text-transform:uppercase}.page-heading h1{margin:0;font-size:24px;letter-spacing:0}.page-heading span{display:block;margin-top:7px;color:#909399;font-size:13px}.heading-actions{display:flex;gap:10px}.metric-grid,.ops-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));border:1px solid #e4e7ed;background:#fff;border-radius:4px}.metric-grid article,.ops-grid article{min-width:0;padding:18px;border-right:1px solid #ebeef5}.metric-grid article:last-child,.ops-grid article:last-child{border-right:0}.metric-grid span,.ops-grid span{display:block;color:#606266;font-size:13px}.metric-grid strong,.ops-grid strong{display:block;margin-top:8px;font-size:25px;letter-spacing:0}.ops-grid{grid-template-columns:repeat(8,minmax(0,1fr))}.ops-grid .el-tag{margin-top:10px}.content-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(360px,.8fr);gap:16px}.table-band{min-width:0;padding:18px 20px;background:#fff;border:1px solid #e4e7ed;border-radius:4px}.section-heading{align-items:center;margin-bottom:14px}.section-heading h2{margin:0;font-size:15px;letter-spacing:0}.section-heading span{color:#909399;font-size:12px}.provider-name{margin-left:8px}.table-band small{display:block;margin-top:3px;color:#909399}.profit{color:#529b2e}.loss{color:#c45656}@media(max-width:1250px){.metric-grid,.ops-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.content-grid{grid-template-columns:1fr}}@media(max-width:700px){.page-heading{flex-direction:column}.metric-grid,.ops-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
